                # or stopping at an intermediate bend still inside it.
                if any(b + resolution < min(a, route_separation_m)
                       for a, b in zip(separation, separation[1:])):
                    continue
        return RallyPose(x, y, math.atan2(target[1] - y, target[0] - x))
